	return expr, nil
}

func splitTemplate(input string) (prefix, expression, suffix string, found bool, err error) {
	if len(input) > maxExpressionBytes {
		return "", "", "", false, trace.BadParameter("expression exceeds the maximum size of %d bytes", maxExpressionBytes)
	}
	trimmed := strings.TrimSpace(input)
	open := strings.Index(trimmed, "{{")
	if open == -1 && !strings.Contains(trimmed, "}}") {
		return "", "", "", false, nil
	}
	if open == -1 || strings.Contains(trimmed[:open], "}}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expected one {{ expression }} block", input)
	}
	close, err := findTemplateClose(trimmed, open+2)
	if err != nil {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: %v", input, err)
	}
	if strings.Contains(trimmed[close+2:], "{{") || strings.Contains(trimmed[close+2:], "}}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expected one {{ expression }} block", input)
	}
	prefix = strings.TrimLeftFunc(trimmed[:open], unicode.IsSpace)
	expression = strings.TrimSpace(trimmed[open+2 : close])
	suffix = strings.TrimRightFunc(trimmed[close+2:], unicode.IsSpace)
	if expression == "" {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expression is empty", input)
	}
	if containsUnquotedBrace(expression) {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: unmatched brace in expression", input)
	}
	return prefix, expression, suffix, true, nil
}


