// Expression is a string expression with optional static text around it.
// namespace, variable, and transform remain available for compatibility with
// callers that inspect expressions; expr is the evaluated representation.
type Expression struct {
	namespace string
	variable  string
	prefix    string
	suffix    string
	transform transformer
	expr      Expr
}

// Namespace returns the namespace of the first variable, or literal for a
// constant expression.
func (p *Expression) Namespace() string {
	if p.namespace != "" {
		return p.namespace
	}
	if vars := expressionVariables(p.expr); len(vars) != 0 {
		return vars[0].Namespace
	}
	return LiteralNamespace
}

// Name returns the name of the first variable or literal expression.
func (p *Expression) Name() string {
	if p.variable != "" {
		return p.variable
	}
	if vars := expressionVariables(p.expr); len(vars) != 0 {
		return vars[0].Name
	}
	if literal, ok := p.expr.(*StringLitExpr); ok {
		return literal.Value
	}
	return ""
}

// Variables returns the variables referenced by this expression in traversal
// order. The returned values do not expose resolved trait values.
func (p *Expression) Variables() []VarExpr {
	return expressionVariables(p.expr)
}

// Interpolate evaluates the expression and applies its static prefix and
// suffix. An optional validator lets callers constrain variable namespaces
// and names for their context.
func (p *Expression) Interpolate(traits map[string][]string, varValidation ...func(namespace, name string) error) ([]string, error) {
	expr := p.expr
	if expr == nil {
		var err error
		expr, err = p.legacyExpr()
		if err != nil {
			return nil, err
		}
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}

	var validate func(string, string) error
	if len(varValidation) != 0 {
		validate = varValidation[0]
	}
	ctx := EvaluateContext{VarValue: func(variable VarExpr) ([]string, error) {
		if validate != nil {
			if err := validate(variable.Namespace, variable.Name); err != nil {
				return nil, trace.Wrap(err)
			}
		}
		if variable.Namespace == LiteralNamespace {
			return []string{variable.Name}, nil
		}
		values, ok := traits[variable.Name]
		if !ok {
			return nil, trace.NotFound("variable %q was not found in traits", variable.String())
		}
		return values, nil
	}}
	values, err := evaluateStrings(expr, ctx, "interpolation expression")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(values) == 0 {
		return nil, trace.NotFound("expression interpolation produced no values")
	}

	result := make([]string, 0, len(values))
	for _, value := range values {
		// Empty evaluated values must not turn a static prefix/suffix into a
		// fabricated interpolation result.
		if value == "" {
			continue
		}
		result = append(result, p.prefix+value+p.suffix)
	}
	if len(result) == 0 {
		return nil, trace.NotFound("expression interpolation produced no values")
	}
	return result, nil
}

func (p *Expression) legacyExpr() (Expr, error) {
	if p.namespace == LiteralNamespace {
		return &StringLitExpr{Value: p.variable}, nil
	}
	namespace := p.namespace
	if namespace == "" {
		// Preserve behavior for expressions constructed directly by older callers.
		namespace = "internal"
	}
	var source Expr = &VarExpr{Namespace: namespace, Name: p.variable}
	switch transform := p.transform.(type) {
	case nil:
		return source, nil
	case emailLocalTransformer:
		return &EmailLocalExpr{Input: source}, nil
	case regexpReplaceTransformer:
		return &RegexpReplaceExpr{Source: source, Pattern: transform.re.String(), Replacement: transform.replacement, re: transform.re}, nil
	case *regexpReplaceTransformer:
		return &RegexpReplaceExpr{Source: source, Pattern: transform.re.String(), Replacement: transform.replacement, re: transform.re}, nil
	default:
		return nil, trace.BadParameter("unsupported expression transformer %T", p.transform)
	}
}

// NewExpression parses a template string or a literal value.
func NewExpression(input string) (*Expression, error) {
	prefix, source, suffix, isTemplate, err := splitTemplate(input)
	if err != nil {
		return nil, err
	}
	if !isTemplate {
		value := strings.TrimSpace(input)
		return &Expression{
			namespace: LiteralNamespace,
			variable:  value,
			expr:      &StringLitExpr{Value: value},
		}, nil
	}

	expr, err := parse(source)
	if err != nil {
		return nil, trace.BadParameter("failed to parse expression %q: %v", input, err)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", input, err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must produce a string, got %s", input, expr.Kind())
	}

	result := &Expression{prefix: prefix, suffix: suffix, expr: expr}
	if variables := expressionVariables(expr); len(variables) != 0 {
		result.namespace = variables[0].Namespace
		result.variable = variables[0].Name
	}
	switch node := expr.(type) {
	case *VarExpr:
	case *EmailLocalExpr:
		if _, ok := node.Input.(*VarExpr); ok {
			result.transform = emailLocalTransformer{}
		}
	case *RegexpReplaceExpr:
		if _, ok := node.Source.(*VarExpr); ok {
			result.transform = &regexpReplaceTransformer{re: node.re, replacement: node.Replacement}
		}
	}
	return result, nil
}

