		return nil, err
	}
	parser, err := predicate.NewParser(predicate.Def{
		Functions: map[string]interface{}{
			EmailNamespace + "." + EmailLocalFnName:      buildEmailLocalExpr,
			RegexpNamespace + "." + RegexpReplaceFnName:  buildRegexpReplaceExpr,
			RegexpNamespace + "." + RegexpMatchFnName:    buildRegexpMatchExpr,
			RegexpNamespace + "." + RegexpNotMatchFnName: buildRegexpNotMatchExpr,
		},
		GetIdentifier: buildVarExpr,
		GetProperty:   buildVarExprFromProperty,
	})
	if err != nil {
		return nil, trace.BadParameter("could not initialize expression parser: %v", err)
	}
	parsed, err := parser.Parse(exprStr)
	if err != nil {
		return nil, trace.BadParameter("unsupported or malformed expression %q: %v", exprStr, err)
	}
	if literal, ok := parsed.(string); ok {
		return &StringLitExpr{Value: literal}, nil
	}
	expr, ok := parsed.(Expr)
	if !ok {
		return nil, trace.BadParameter("invalid variable expression %q: expected namespace.name or namespace[\"name\"], got %T", exprStr, parsed)
	}
	return expr, nil
}

func buildVarExpr(selector []string) (interface{}, error) {
	if len(selector) == 0 {
		return nil, trace.BadParameter("expected a two-part variable in namespace.name form")
	}
	if len(selector) > 2 {
		return nil, trace.BadParameter("invalid variable %q: expected exactly namespace.name or namespace[\"name\"]", strings.Join(selector, "."))
	}
	variable := &VarExpr{Namespace: selector[0]}
	if len(selector) == 2 {
		variable.Name = selector[1]
	}
	return variable, nil
}

func buildVarExprFromProperty(mapValue, keyValue interface{}) (interface{}, error) {
	variable, ok := mapValue.(*VarExpr)
	if !ok || variable.Name != "" {
		return nil, trace.BadParameter("invalid variable selector: expected exactly namespace[\"name\"]")
	}
	name, ok := keyValue.(string)
	if !ok {
		return nil, trace.BadParameter("invalid variable selector: the bracketed name must be a string literal")
	}
	return &VarExpr{Namespace: variable.Namespace, Name: name}, nil
}

func buildEmailLocalExpr(args ...interface{}) (Expr, error) {
	if len(args) != 1 {
		return nil, trace.BadParameter("email.local expects exactly 1 argument, got %d", len(args))
	}
	input, err := stringExpression(args[0], "email.local argument")
	if err != nil {
		return nil, err
	}
	return &EmailLocalExpr{Input: input}, nil
}

func buildRegexpReplaceExpr(args ...interface{}) (Expr, error) {
	if len(args) != 3 {
		return nil, trace.BadParameter("regexp.replace expects exactly 3 arguments, got %d", len(args))
	}
	source, err := stringExpression(args[0], "regexp.replace source")
	if err != nil {
		return nil, err
	}
	pattern, ok := args[1].(string)
	if !ok {
		return nil, trace.BadParameter("regexp.replace pattern must be a constant string literal")
	}
	replacement, ok := args[2].(string)
	if !ok {
		return nil, trace.BadParameter("regexp.replace replacement must be a constant string literal")
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return &RegexpReplaceExpr{Source: source, Pattern: pattern, Replacement: replacement, re: re}, nil
}

func buildRegexpMatchExpr(args ...interface{}) (Expr, error) {
	return buildRegexpPredicate(args, false)
}

func buildRegexpNotMatchExpr(args ...interface{}) (Expr, error) {
	return buildRegexpPredicate(args, true)
}

func buildRegexpPredicate(args []interface{}, negate bool) (Expr, error) {
	name := RegexpMatchFnName
	if negate {
		name = RegexpNotMatchFnName
	}
	if len(args) != 1 {
		return nil, trace.BadParameter("regexp.%s expects exactly 1 argument, got %d", name, len(args))
	}
	pattern, ok := args[0].(string)
	if !ok {
		return nil, trace.BadParameter("regexp.%s pattern must be a constant string literal", name)
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	if negate {
		return &RegexpNotMatchExpr{Pattern: pattern, re: re}, nil
	}
	return &RegexpMatchExpr{Pattern: pattern, re: re}, nil
}

func stringExpression(value interface{}, position string) (Expr, error) {
	if literal, ok := value.(string); ok {
		return &StringLitExpr{Value: literal}, nil
	}
	expr, ok := value.(Expr)
	if !ok {
		return nil, trace.BadParameter("%s must be a string expression, got %T", position, value)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("%s must be a string expression, got %s", position, expr.Kind())
	}
	return expr, nil
}

func splitTemplate(input string) (prefix, expression, suffix string, found bool, err error) {
	if len(input) > maxExpressionBytes {
		return "", "", "", false, trace.BadParameter("expression exceeds the maximum size of %d bytes", maxExpressionBytes)
	}
	trimmed := strings.TrimSpace(input)
	open := strings.Index(trimmed, "{{")
	if open == -1 && !strings.Contains(trimmed, "}}") {
		return "", "", "", false, nil
	}
	if open == -1 || strings.Contains(trimmed[:open], "}}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expected one {{ expression }} block", input)
	}
	close, err := findTemplateClose(trimmed, open+2)
	if err != nil {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: %v", input, err)
	}
	if strings.Contains(trimmed[close+2:], "{{") || strings.Contains(trimmed[close+2:], "}}") {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expected one {{ expression }} block", input)
	}
	prefix = strings.TrimLeftFunc(trimmed[:open], unicode.IsSpace)
	expression = strings.TrimSpace(trimmed[open+2 : close])
	suffix = strings.TrimRightFunc(trimmed[close+2:], unicode.IsSpace)
	if expression == "" {
		return "", "", "", false, trace.BadParameter("malformed template usage in %q: expression is empty", input)
	}
	return prefix, expression, suffix, true, nil
}

func findTemplateClose(source string, start int) (int, error) {
	var quote byte
	escaped := false
	for i := start; i < len(source); i++ {
		char := source[i]
		if quote != 0 {
			if quote != '`' && escaped {
				escaped = false
				continue
			}
			if quote != '`' && char == '\\' {
				escaped = true
				continue
			}
			if char == quote {
				quote = 0
			}
			continue
		}
		switch char {
		case '"', '\'', '`':
			quote = char
		case '{':
			if i+1 < len(source) && source[i+1] == '{' {
				return -1, trace.BadParameter("nested opening delimiter")
			}
			return -1, trace.BadParameter("unmatched opening brace")
		case '}':
			if i+1 < len(source) && source[i+1] == '}' {
				return i, nil
			}
			return -1, trace.BadParameter("unmatched closing brace")
		}
	}
	return -1, trace.BadParameter("missing closing delimiter")
}

func checkExpressionDepth(source string) error {
	depth := 0
	selectors := 0
	indexes := 0
	operators := 0
	quote := rune(0)
	escaped := false
	for _, char := range source {
		if quote != 0 {
			if quote != '`' && escaped {
				escaped = false
				continue
			}
			if quote != '`' && char == '\\' {
				escaped = true
				continue
			}
			if char == quote {
				quote = 0
			}
			continue
		}
		switch char {
		case '"', '\'', '`':
			quote = char
		case '(':
			depth++
			if depth > maxExpressionDepth {
				return trace.BadParameter("expression exceeds the maximum nesting depth of %d", maxExpressionDepth)
			}
		case '[':
			depth++
			indexes++
			if depth > maxExpressionDepth {
				return trace.BadParameter("expression exceeds the maximum nesting depth of %d", maxExpressionDepth)
			}
			if indexes > 1 {
				return trace.BadParameter("invalid variable selector: expected exactly namespace[\"name\"]")
			}
		case ')', ']':
			depth--
			if depth < 0 {
				return trace.BadParameter("malformed expression: unexpected closing delimiter")
			}
		case '.':
			selectors++
			if selectors > maxExpressionDepth {
				return trace.BadParameter("expression exceeds the maximum nesting depth of %d", maxExpressionDepth)
			}
		case ',', '+', '-', '*', '/', '%', '&', '|', '!', '=', '<', '>', '^':
			operators++
			if operators > maxExpressionDepth {
				return trace.BadParameter("expression exceeds the maximum nesting depth of %d", maxExpressionDepth)
			}
		}
	}
	if depth != 0 || quote != 0 {
		return trace.BadParameter("malformed expression: unclosed delimiter or string literal")
	}
	return nil
}

func expressionVariables(expr Expr) []VarExpr {
	var result []VarExpr
	var visit func(Expr)
	visit = func(node Expr) {
		switch value := node.(type) {
		case *VarExpr:
			result = append(result, *value)
		case *EmailLocalExpr:
			visit(value.Input)
		case *RegexpReplaceExpr:
			visit(value.Source)
		}
	}
	visit(expr)
	return result
}

// Matcher matches a string against a matcher expression.
type Matcher interface {
	Match(in string) bool
}

// MatcherFn converts a function to a matcher.
type MatcherFn func(in string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }

// MatchExpression combines static prefix/suffix checks with a boolean AST.
type MatchExpression struct {
	Prefix  string
	Suffix  string
	Matcher Expr
}

func (m *MatchExpression) Match(in string) bool {
	if m == nil || m.Matcher == nil || !strings.HasPrefix(in, m.Prefix) || !strings.HasSuffix(in, m.Suffix) {
		return false
	}
	if len(in) < len(m.Prefix)+len(m.Suffix) {
		return false
	}
	end := len(in) - len(m.Suffix)
	middle := in[len(m.Prefix):end]
	value, err := m.Matcher.Evaluate(EvaluateContext{MatcherInput: middle})
	matched, ok := value.(bool)
	return err == nil && ok && matched
}

// NewAnyMatcher returns a matcher that matches if any input pattern matches.
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, value := range in {
		matcher, err := NewMatcher(value)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = matcher
	}
	return MatcherFn(func(value string) bool {
		for _, matcher := range matchers {
			if matcher.Match(value) {
				return true
			}
		}
		return false
	}), nil
}

// NewMatcher parses literal, glob, raw-regexp, and boolean regexp templates.
func NewMatcher(value string) (Matcher, error) {
	prefix, source, suffix, isTemplate, err := splitTemplate(value)
	if err != nil {
		return nil, err
	}
	if !isTemplate {
		pattern := strings.TrimSpace(value)
		if !strings.HasPrefix(pattern, "^") || !strings.HasSuffix(pattern, "$") {
			pattern = globPattern(pattern)
		}
		re, err := compileRegexp(pattern)
		if err != nil {
			return nil, err
		}
		return &MatchExpression{Matcher: &RegexpMatchExpr{Pattern: pattern, re: re}}, nil
	}

	expr, err := parse(source)
	if err != nil {
		return nil, trace.BadParameter("failed to parse matcher expression %q: %v", value, err)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.BadParameter("invalid matcher expression %q: %v", value, err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher expression %q must produce a boolean, got %s", value, expr.Kind())
	}
	return &MatchExpression{Prefix: prefix, Suffix: suffix, Matcher: expr}, nil
}

func globPattern(value string) string {
	var result strings.Builder
	result.WriteByte('^')
	for _, char := range value {
		if char == '*' {
			result.WriteString(".*")
			continue
		}
		result.WriteString(regexp.QuoteMeta(string(char)))
	}
	result.WriteByte('$')
	return result.String()
}

// regexpMatcher, prefixSuffixMatcher, and notMatcher retain compatibility for
// callers and tests that construct matchers directly.
type regexpMatcher struct{ re *regexp.Regexp }

func (m regexpMatcher) Match(in string) bool { return m.re.MatchString(in) }

type prefixSuffixMatcher struct {
	prefix, suffix string
	m              Matcher
}

func (m prefixSuffixMatcher) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) || len(in) < len(m.prefix)+len(m.suffix) {
		return false
	}
	in = in[len(m.prefix) : len(in)-len(m.suffix)]
	return m.m.Match(in)
}

type notMatcher struct{ m Matcher }

func (m notMatcher) Match(in string) bool { return !m.m.Match(in) }

type transformer interface {
	transform(in string) (string, error)
}

type emailLocalTransformer struct{}

func (emailLocalTransformer) transform(in string) (string, error) {
	values, err := (&EmailLocalExpr{Input: &StringLitExpr{Value: in}}).Evaluate(EvaluateContext{})
	if err != nil {
		return "", err
	}
	return values.([]string)[0], nil
}

type regexpReplaceTransformer struct {
	re          *regexp.Regexp
	replacement string
}

func newRegexpReplaceTransformer(pattern, replacement string) (*regexpReplaceTransformer, error) {
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return &regexpReplaceTransformer{re: re, replacement: replacement}, nil
}
